const r = $input.first().json;
const fact = r.overdue > 0
  ? `${r.name} has ${r.overdue} overdue task(s).`
  : `${r.name} is behind on syllabus this month.`;
const ask = r.overdue > 0
  ? 'Ask: can they close one task before tomorrow 8pm?'
  : 'Ask: advisor to mark stage or trigger a sprint.';
return [{ json: { ...r, body: `${fact} ${ask}` } }];
